enriched = 0
for failure in d["failures"]:
    fid = failure["id"]
    if fid in CS and not failure.get("case_studies"):
        failure["case_studies"] = CS[fid]
        enriched += 1
        print(f"{fid}: {len(CS[fid])} case stud(ies) added")

DATA.write_text(json.dumps(d, indent=2, ensure_ascii=False))
print(f"Batch C: enriched {enriched} classes")
